const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const session_id = Number(input.session_id);
const message_id = Number(input.message_id);
const confidence_threshold = Number(input.confidence_threshold ?? 0.55);
const confirm_evaluation = toBoolean(input.confirm_evaluation);

const errors = [];

if (!Number.isInteger(session_id) || session_id < 1) {
  errors.push({
    field: 'session_id',
    message: 'session_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!Number.isInteger(message_id) || message_id < 1) {
  errors.push({
    field: 'message_id',
    message: 'message_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (
  !Number.isFinite(confidence_threshold) ||
  confidence_threshold < 0 ||
  confidence_threshold > 1
) {
  errors.push({
    field: 'confidence_threshold',
    message: 'آستانه اطمینان باید عددی بین صفر و یک باشد.',
  });
}

if (confirm_evaluation !== true) {
  errors.push({
    field: 'confirm_evaluation',
    message: 'اجرای Safety Gate باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    session_id,
    message_id,
    confidence_threshold,
    confirm_evaluation,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

if ($json.success !== true) {
  return [{ json: $json }];
}

const context = $json.safety_context || {};
const ai = context.ai_output || {};

const uniqueStrings = (value) => {
  if (!Array.isArray(value)) return [];
  return [...new Set(
    value
      .map((item) => String(item || '').trim())
      .filter(Boolean)
  )];
};

const riskFlags = uniqueStrings(
  ai.risk_flags ??
  context.message_risk_flags ??
  []
).filter((item) => item !== 'none');

const missingFields = uniqueStrings(ai.missing_fields ?? []);
const intent = String(ai.intent || context.intent || 'unclear');
const confidence = Math.max(
  0,
  Math.min(
    1,
    Number(ai.confidence ?? context.intent_confidence ?? 0)
  )
);

const proposedTool = String(
  ai.tool_action ||
  context.proposed_tool_action ||
  'none'
);

const requiresHuman = Boolean(ai.requires_human);
const requiresConfirmation = Boolean(ai.requires_confirmation);
const nextQuestion =
  ai.next_question === null || ai.next_question === undefined
    ? null
    : String(ai.next_question).trim() || null;

const entities =
  ai.entities &&
  typeof ai.entities === 'object' &&
  !Array.isArray(ai.entities)
    ? ai.entities
    : (
        context.extracted_entities &&
        typeof context.extracted_entities === 'object'
          ? context.extracted_entities
          : {}
      );

const urgentRiskFlags = [
  'breathing_difficulty',
  'face_lip_tongue_swelling',
  'loss_of_consciousness',
  'seizure',
  'chest_pain',
  'possible_overdose',
  'severe_bleeding',
  'self_harm_or_violence',
];

const writeTools = [
  'create_appointment',
  'cancel_appointment',
  'reschedule_appointment',
  'process_confirmation_response',
  'process_waitlist_response',
];

const sensitiveIntents = [
  'medication_issue',
  'emergency',
];

const urgentFlags = riskFlags.filter(
  (flag) => urgentRiskFlags.includes(flag)
);

let safetyDecision = 'allow';
let safeToolAction = proposedTool;
let blockReason = null;
let patientFacingInstruction = null;
let sessionStatus = 'active';
let pendingAction = null;
let nextAction = 'route_tool';

if (urgentFlags.length > 0 || intent === 'emergency') {
  safetyDecision = 'urgent_handoff';
  safeToolAction = 'urgent_human_handoff';
  blockReason = 'urgent_risk_detected';
  patientFacingInstruction =
    'این پیام می‌تواند نشان‌دهنده وضعیت فوری باشد. بیمار نباید منتظر پاسخ خودکار بماند و باید فوراً از خدمات اورژانسی محلی یا کمک حضوری استفاده کند.';
  sessionStatus = 'waiting_human';
  pendingAction = 'urgent_human_handoff';
  nextAction = 'create_urgent_handoff';

} else if (
  confidence < Number(context.confidence_threshold ?? 0.55) ||
  intent === 'unclear'
) {
  safetyDecision = 'ask_clarification';
  safeToolAction = 'none';
  blockReason = 'low_confidence_or_unclear_intent';
  patientFacingInstruction =
    nextQuestion ||
    'لطفاً درخواست خود را با جزئیات بیشتری توضیح دهید.';
  sessionStatus = 'waiting_patient';
  pendingAction = proposedTool !== 'none'
    ? proposedTool
    : null;
  nextAction = 'ask_clarifying_question';

} else if (missingFields.length > 0) {
  safetyDecision = 'ask_missing_information';
  safeToolAction = 'none';
  blockReason = 'required_information_missing';
  patientFacingInstruction =
    nextQuestion ||
    'برای ادامه، اطلاعات تکمیلی موردنیاز را ارسال کنید.';
  sessionStatus = 'waiting_patient';
  pendingAction = proposedTool !== 'none'
    ? proposedTool
    : null;
  nextAction = 'ask_missing_information';

} else if (
  writeTools.includes(proposedTool) &&
  requiresConfirmation === true
) {
  safetyDecision = 'request_confirmation';
  safeToolAction = 'none';
  blockReason = 'explicit_confirmation_required';
  patientFacingInstruction =
    nextQuestion ||
    'لطفاً انجام این اقدام را با ذکر جزئیات نهایی تأیید کنید.';
  sessionStatus = 'waiting_patient';
  pendingAction = proposedTool;
  nextAction = 'request_action_confirmation';

} else if (
  riskFlags.includes('privacy_concern') ||
  (
    requiresHuman === true &&
    !sensitiveIntents.includes(intent)
  )
) {
  safetyDecision = 'human_handoff';
  safeToolAction = 'human_handoff';
  blockReason = riskFlags.includes('privacy_concern')
    ? 'privacy_or_sensitive_data_concern'
    : 'ai_requested_human_review';
  patientFacingInstruction =
    'درخواست شما برای بررسی به مسئول انسانی ارجاع شد.';
  sessionStatus = 'waiting_human';
  pendingAction = 'human_handoff';
  nextAction = 'create_human_handoff';

} else if (intent === 'medication_issue') {
  safetyDecision = 'allow_with_human_review';
  safeToolAction = 'intake_medication_issue';
  blockReason = 'medication_issue_requires_structured_intake';
  patientFacingInstruction = null;
  sessionStatus = 'active';
  pendingAction = 'intake_medication_issue';
  nextAction = 'route_tool';

} else if (proposedTool === 'none') {
  safetyDecision = 'response_only';
  safeToolAction = 'none';
  blockReason = null;
  patientFacingInstruction = nextQuestion;
  sessionStatus = 'active';
  pendingAction = null;
  nextAction = 'compose_response';
}

const safetyPayload = {
  stage: 'deterministic_safety_gate',
  version: 'safety-v1',
  evaluated_at: new Date().toISOString(),
  safety_decision: safetyDecision,
  proposed_tool_action: proposedTool,
  safe_tool_action: safeToolAction,
  block_reason: blockReason,
  urgent_flags: urgentFlags,
  risk_flags: riskFlags,
  missing_fields: missingFields,
  requires_human: requiresHuman,
  requires_confirmation: requiresConfirmation,
  patient_facing_instruction: patientFacingInstruction,
  next_action: nextAction,
};

return [{
  json: {
    success: true,
    result: 'safety_decision_created',
    session_id: Number(context.session_id),
    message_id: Number(context.message_id),
    ai_run_id: context.ai_run_id ?? null,
    clinic_name: context.clinic_name,
    patient_name: context.patient_name,
    mobile: context.mobile,
    language: ai.language || context.session_language || 'unknown',
    intent,
    confidence,
    entities,
    entities_json: JSON.stringify(entities),
    risk_flags: riskFlags,
    risk_flags_json: JSON.stringify(riskFlags),
    missing_fields: missingFields,
    safety_decision: safetyDecision,
    proposed_tool_action: proposedTool,
    safe_tool_action: safeToolAction,
    block_reason: blockReason,
    patient_facing_instruction: patientFacingInstruction,
    session_status: sessionStatus,
    pending_action: pendingAction,
    next_action: nextAction,
    safety_payload: safetyPayload,
    safety_payload_json: JSON.stringify(safetyPayload),
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات لازم برای Safety Gate ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];

return [{
  json: {
    success: false,
    result: $json.result || 'safety_context_not_available',
    message:
      $json.result === 'ai_route_not_found'
        ? 'ابتدا پیام باید توسط Workflow شماره 51 تحلیل شود.'
        : 'پیام یا جلسه مکالمه پیدا نشد.',
  },
}];
